solution.code:
// Correct: augment additively, or declare every export you use.
// declare module 'date-utils' {
//   export function parse(s: string): Date;
//   export function format(d: Date): string; // include the rest
// }

function parse(s: string) { return new Date(s); }
function format(d: Date) { return d.toISOString(); }

console.log(typeof format(parse('2026-06-23')) === 'string');

